class topology_projector {
public:
	json build(double time,
	           const json::array_t &streams_list,
	           const json::array_t &interface_list,
	           const json::array_t &metrics_list,
	           const json::array_t &active_alerts = json::array_t{}) const;

private:
	struct endpoint_parts {
		std::string host;
		int port{0};
		bool has_port{false};
	};

	struct metric_summary {
		json metrics{json::object()};
	};

	struct alert_index {
		std::unordered_map<std::string, std::vector<json>> by_flow;
		std::unordered_map<std::string, std::vector<json>> by_stream;
		std::unordered_map<std::string, std::vector<json>> by_interface;
	};

	static std::unordered_map<std::string, std::string> build_interface_names(const json::array_t &interface_list);
	static std::unordered_map<std::string, metric_summary> build_metric_index(const json::array_t &metrics_list);
	static alert_index build_alert_index(const json::array_t &active_alerts);
	static std::string metric_key(const std::string &stream_key, const std::string &flow_key);
	static endpoint_parts parse_endpoint(const std::string &value);
	static std::string transport_from_entry(const json &stream_entry, const json &flow_entry, const json *metric_entry);
	static std::string transport_from_ip_proto(int ip_proto);
	static std::string transport_from_proto(const std::string &proto);
	static bool is_group_host(const std::string &host);
	static bool is_ipv4_broadcast(const std::string &host);
	static bool is_ipv4_multicast(const std::string &host);
	static bool is_ipv6_multicast(const std::string &host);
	static bool service_role_for_endpoint(const endpoint_parts &self, const endpoint_parts &peer, const std::string &transport, bool is_src);
	static std::string node_id_for_endpoint(const endpoint_parts &endpoint, const std::string &transport, bool service_role);
	static json make_node_for_endpoint(const endpoint_parts &endpoint, const std::string &transport, bool service_role);
	static json make_scope(const json &stream, const json &flow, const std::unordered_map<std::string, std::string> &interface_names);
	static json summarize_metrics(const json &entry);
	static json summarize_alerts(const std::vector<json> &alerts);
	static int severity_rank(const std::string &severity);
	static void append_matching_alerts(std::vector<json> &out, const alert_index &alerts, const std::string &stream_key, const std::string &flow_key, const json &scope);
	static void merge_node_alert(std::unordered_map<std::string, json> &nodes, const std::string &node_id, const json &alert_summary);
	static void upsert_node(std::unordered_map<std::string, json> &nodes, json node);
};

