function filterTopologyGraph(graph: ReturnType<typeof buildTopologyGraph>, query: string, streamDisplayNames: ReadonlyMap<string, string>) {
  if (!query.trim()) return graph;

  const matchingNodeIds = new Set(graph.nodes
    .filter((node) => matchesSearch([
      node.id,
      node.label,
      node.host,
      ...node.services.flatMap((service) => [service.label, service.port, service.transport, service.proto])
    ], query))
    .map((node) => node.id));
  const matchingEdges = graph.edges.filter((edge) =>
    matchingNodeIds.has(edge.srcHostId) ||
    matchingNodeIds.has(edge.dstHostId) ||
    matchesSearch([
      edge.id,
      edge.src,
      edge.dst,
      edge.proto,
      edge.transport,
      edge.state,
      edge.role,
      edge.identity?.stream_key,
      edge.identity?.flow_key,
      edge.identity?.stream_key ? streamDisplayNames.get(edge.identity.stream_key) : undefined,
      endpointString(edge.endpoint?.src),
      endpointString(edge.endpoint?.dst)
    ], query));
  const visibleNodeIds = new Set(matchingNodeIds);
  for (const edge of matchingEdges) {
    visibleNodeIds.add(edge.srcHostId);
    visibleNodeIds.add(edge.dstHostId);
  }
  const nodes = graph.nodes.filter((node) => visibleNodeIds.has(node.id));
  const edgeIds = new Set(matchingEdges.map((edge) => edge.id));
  return {
    ...graph,
    nodes,
    edges: matchingEdges,
    scopes: graph.scopes.map((scope) => ({
      ...scope,
      nodeIds: scope.nodeIds.filter((nodeId) => visibleNodeIds.has(nodeId)),
      edgeIds: scope.edgeIds.filter((edgeId) => edgeIds.has(edgeId))
    })).filter((scope) => scope.nodeIds.length > 0 || scope.edgeIds.length > 0),
    nodeById: new Map(nodes.map((node) => [node.id, node]))
  };
}

function automaticPositionsFor(positions: Map<TopologyLayoutMode, Map<string, XYPosition>>, layoutMode: TopologyLayoutMode) {
  const existing = positions.get(layoutMode);
  if (existing) return existing;
  const next = new Map<string, XYPosition>();
  positions.set(layoutMode, next);
  return next;
}

function positionGraphNodes(graph: ReturnType<typeof buildTopologyGraph>, manualPositions: Map<string, XYPosition>, automaticPositions: Map<string, XYPosition>) {
  return {
    ...graph,
    nodes: graph.nodes.map((node) => {
      const position = manualPositions.get(node.id) ?? automaticPositions.get(node.id);
      return position ? { ...node, x: position.x, y: position.y } : node;
    })
  };
}

function readTopologyLayoutMode(): TopologyLayoutMode {
  if (typeof window === "undefined") return "balanced";
  try {
    const value = window.localStorage.getItem(TOPOLOGY_LAYOUT_STORAGE_KEY);
    return value === "vertical" || value === "horizontal" || value === "balanced" ? value : "balanced";
  } catch {
    return "balanced";
  }
}

function cloneSnapshot(snapshot: TopologySnapshot | null) {
  if (!snapshot) return null;
  return {
    ...snapshot,
    nodes: snapshot.nodes.map((node) => ({ ...node })),
    edges: snapshot.edges.map((edge) => ({ ...edge }))
  };
}

function flowMapSnapshot(response: TopologyRelationFlowsResponse): TopologySnapshot {
  return {
    time: response.relation.last_seen ?? Date.now() / 1000,
    nodes: [],
    /* Flow map preserves every raw flow's endpoint direction. */
    edges: response.flows.map((flow) => ({ ...flow }))
  };
}

function buildReactFlowModel(nodes: ReturnType<typeof buildTopologyGraph>["nodes"], edges: TopologyGraphEdge[], selectedEdgeIds: Set<string>, selectedNodeIds: Set<string>, selectedEndpointKeys: Set<string>, onSelectEndpoint: (nodeId: string, serviceKey: string) => void) {
  const nodesById = new Map(nodes.map((node) => [node.id, node]));
  const rfNodes: Node<TopologyNodeData>[] = nodes.map((node) => ({
    id: node.id,
    type: "topologySchema",
    position: { x: node.x, y: node.y },
    className: `topology-rf-node topology-rf-node-${node.type} ${node.state === "stale" ? "topology-rf-node-stale" : ""} ${node.alert ? "topology-rf-node-alert" : ""} ${selectedNodeIds.has(node.id) ? "topology-rf-node-selected" : ""}`,
    data: {
      host: node.host,
      nodeId: node.id,
      alert: node.alert,
      selectedEndpointKeys,
      onSelectEndpoint,
      label: node.label,
      services: node.services.slice(0, MAX_VISIBLE_SERVICES),
      hiddenServiceCount: Math.max(0, node.services.length - MAX_VISIBLE_SERVICES),
      state: node.state
    }
  }));

  const rfEdges: TopologyFlowEdge[] = edges.map((edge) => {
    const selected = selectedEdgeIds.has(edge.id);
    const alert = Boolean(edge.alert);
    const stale = edge.state === "stale";
    const label = `${portPairLabel(edge)}${flowCountLabel(edge.flow_summary)}${stale ? " · stale" : ""}`;
    const stroke = alert ? "var(--danger)" : selected ? "var(--accent)" : edge.state === "active" ? "var(--accent-2)" : "var(--muted)";
    const bidirectional = (edge.flow_summary?.to_service_count ?? 0) > 0 && (edge.flow_summary?.from_service_count ?? 0) > 0;
    return {
      id: edge.id,
      source: edge.srcHostId,
      target: edge.dstHostId,
      sourceHandle: topologyHandleId("source", renderedServiceHandle(nodesById.get(edge.srcHostId), edge.srcServiceKey)),
      targetHandle: topologyHandleId("target", renderedServiceHandle(nodesById.get(edge.dstHostId), edge.dstServiceKey)),
      type: "topology",
      animated: alert && !stale,
      label,
      className: `topology-rf-edge ${edge.state === "active" ? "active" : "stale"} ${alert ? "alert" : ""} ${selected ? "selected" : ""}`,
      markerStart: bidirectional ? { type: MarkerType.ArrowClosed, color: stroke } : undefined,
      markerEnd: { type: MarkerType.ArrowClosed, color: stroke },
      style: {
        strokeWidth: bitrateStrokeWidth(edge, selected),
        stroke: stale ? "var(--muted)" : stroke
      },
      interactionWidth: selected ? 28 : 18,
      zIndex: selected ? 1000 : alert ? 200 : 10,
      data: { edge, label }
    };
  });

  return { nodes: rfNodes, edges: rfEdges };
}

